<?php

namespace App\Http\Requests\Hr;

use App\Models\Hr\AttendanceDevice;

/** Mobile device registration: the installation id generated by the application and descriptive metadata. */
class MobileDeviceRequest extends HrFormRequest
{
    public function rules(): array
    {
        return [
            'device_uuid' => ['required', 'string', 'min:8', 'max:100', 'regex:/^[A-Za-z0-9._:-]+$/'],
            'platform' => ['required', 'string', 'in:'.implode(',', AttendanceDevice::PLATFORMS)],
            'device_name' => ['nullable', 'string', 'max:100'],
            'device_model' => ['nullable', 'string', 'max:100'],
            'os_version' => ['nullable', 'string', 'max:50'],
            'app_version' => ['nullable', 'string', 'max:50'],
        ];
    }
}
